    {converting&&<div className="conversion-progress" role="status"><House size={30}/><h3>{scan>=1?tr('Your floor plan has come to life','平面图已经立起来了','平面圖已經立起來了'):tr('Building your 3D preview','正在建立 3D 预览','正在建立 3D 預覽')}</h3><p>{scan<.34?tr('Reading the floor plan','读取平面图','讀取平面圖'):scan<.68?tr('Identifying walls and openings','识别墙体与门窗','識別牆體與門窗'):tr('Reconstructing the demo home','重建示例户型','重建範例戶型')}</p><div className="conversion-meter"><span>{Math.round(scan*100)}%</span><progress max={1} value={scan} aria-label={tr('Reconstruction progress','重建进度','重建進度')}/></div><small>{tr('Demo conversion · uses the current sample apartment','模拟转换 · 使用当前示例户型','模擬轉換 · 使用目前範例戶型')}</small></div>}{scanning&&<><div className={styles.scanChecklist}>{scanSteps.slice(0,phase==='new-scan'?4:5).map((s,i)=><div key={s} className={i<=scanIndex(scan)?styles.scanComplete:''}><span>{i<scanIndex(scan)?<Check size={12}/>:String(i+1).padStart(2,'0')}</span><p>{t(s)}</p>{i===scanIndex(scan)&&<i className={styles.workingDot}/>}</div>)}</div><div className={styles.scanNumbers}><strong>{scanSamples.toLocaleString()}</strong><span>{t("simulated surface samples")}</span>{old&&<small>{identifiedFurniture(scan)}{t("/ 18 furniture groups identified")}</small>}</div></>}
